-- 阶段5：实验任务与电子实验记录。菜单和角色权限由 LabExperimentInitializer 幂等维护。
DECLARE
    table_count NUMBER;
    PROCEDURE ensure_table(name VARCHAR2, ddl CLOB) IS
    BEGIN
        SELECT COUNT(*) INTO table_count FROM USER_TABLES WHERE TABLE_NAME=name;
        IF table_count=0 THEN EXECUTE IMMEDIATE ddl; END IF;
    END;
BEGIN
    ensure_table('HXS_LAB_EXPERIMENT', q'[CREATE TABLE HXS_LAB_EXPERIMENT (ID RAW(16) NOT NULL, EXPERIMENT_NO VARCHAR2(40 CHAR) NOT NULL, EXPERIMENT_NAME VARCHAR2(150 CHAR) NOT NULL, GROUP_ID RAW(16), OWNER_ID RAW(16) NOT NULL, TOPIC_NAME VARCHAR2(150 CHAR), PURPOSE VARCHAR2(1000 CHAR) NOT NULL, STATUS VARCHAR2(20 CHAR) NOT NULL, START_TIME TIMESTAMP(6), END_TIME TIMESTAMP(6), ARCHIVE_USER_ID RAW(16), ARCHIVE_TIME TIMESTAMP(6), CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_HXS_LAB_EXPERIMENT PRIMARY KEY(ID), CONSTRAINT UK_HXS_LAB_EXPERIMENT_NO UNIQUE(EXPERIMENT_NO), CONSTRAINT CK_HXS_LAB_EXPERIMENT_STATUS CHECK(STATUS IN ('draft','in_progress','completed','archived')), CONSTRAINT FK_EXP_GROUP FOREIGN KEY(GROUP_ID) REFERENCES HXS_LAB_GROUP(ID), CONSTRAINT FK_EXP_OWNER FOREIGN KEY(OWNER_ID) REFERENCES HXS_SYS_USER(ID), CONSTRAINT FK_EXP_ARCHIVE_USER FOREIGN KEY(ARCHIVE_USER_ID) REFERENCES HXS_SYS_USER(ID))]');
    ensure_table('HXS_LAB_EXPERIMENT_INSTRUMENT', q'[CREATE TABLE HXS_LAB_EXPERIMENT_INSTRUMENT (ID RAW(16) NOT NULL, EXPERIMENT_ID RAW(16) NOT NULL, INSTRUMENT_ID RAW(16) NOT NULL, BOOKING_ID RAW(16), CONSTRAINT PK_HXS_LAB_EXP_INSTRUMENT PRIMARY KEY(ID), CONSTRAINT UK_HXS_LAB_EXP_INSTRUMENT UNIQUE(EXPERIMENT_ID,INSTRUMENT_ID), CONSTRAINT FK_EXP_INS_EXP FOREIGN KEY(EXPERIMENT_ID) REFERENCES HXS_LAB_EXPERIMENT(ID), CONSTRAINT FK_EXP_INS_INS FOREIGN KEY(INSTRUMENT_ID) REFERENCES HXS_LAB_INSTRUMENT(ID), CONSTRAINT FK_EXP_INS_BOOKING FOREIGN KEY(BOOKING_ID) REFERENCES HXS_LAB_BOOKING(ID))]');
    ensure_table('HXS_LAB_EXPERIMENT_MATERIAL', q'[CREATE TABLE HXS_LAB_EXPERIMENT_MATERIAL (ID RAW(16) NOT NULL, EXPERIMENT_ID RAW(16) NOT NULL, MATERIAL_ID RAW(16) NOT NULL, REQUISITION_ID RAW(16), QUANTITY NUMBER(18,4) NOT NULL, CONSTRAINT PK_HXS_LAB_EXP_MATERIAL PRIMARY KEY(ID), CONSTRAINT UK_HXS_LAB_EXP_MATERIAL UNIQUE(EXPERIMENT_ID,MATERIAL_ID), CONSTRAINT CK_HXS_LAB_EXP_MAT_QTY CHECK(QUANTITY>0), CONSTRAINT FK_EXP_MAT_EXP FOREIGN KEY(EXPERIMENT_ID) REFERENCES HXS_LAB_EXPERIMENT(ID), CONSTRAINT FK_EXP_MAT_MAT FOREIGN KEY(MATERIAL_ID) REFERENCES HXS_LAB_MATERIAL(ID), CONSTRAINT FK_EXP_MAT_REQ FOREIGN KEY(REQUISITION_ID) REFERENCES HXS_LAB_REQUISITION(ID))]');
    ensure_table('HXS_LAB_EXPERIMENT_RECORD', q'[CREATE TABLE HXS_LAB_EXPERIMENT_RECORD (ID RAW(16) NOT NULL, EXPERIMENT_ID RAW(16) NOT NULL, RECORD_TYPE VARCHAR2(30 CHAR) NOT NULL, CONTENT VARCHAR2(4000 CHAR) NOT NULL, RECORD_TIME TIMESTAMP(6) NOT NULL, CREATOR_ID RAW(16) NOT NULL, CONSTRAINT PK_HXS_LAB_EXP_RECORD PRIMARY KEY(ID), CONSTRAINT FK_EXP_RECORD_EXP FOREIGN KEY(EXPERIMENT_ID) REFERENCES HXS_LAB_EXPERIMENT(ID), CONSTRAINT FK_EXP_RECORD_USER FOREIGN KEY(CREATOR_ID) REFERENCES HXS_SYS_USER(ID))]');
END;
/
COMMIT;
